def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # Prime factorization with multiplicity
    factors = []
    temp = a

    # Try all possible prime factors from 2 to sqrt(a)
    for d in range(2, int(temp**0.5) + 1):
        if is_prime(d):
            while temp % d == 0:
                factors.append(d)
                temp //= d
            if temp == 1:
                break

    # If there's still a number left (must be prime)
    if temp > 1:
        if is_prime(temp):
            factors.append(temp)

    return len(factors) == 3
