def dict_depth(d):
    def helper(depth):
        if not isinstance(d, dict):
            return depth
        max_d = depth
        for value in d.values():
            if isinstance(value, dict):
                new_max = helper(depth + 1)
                max_d = max(max_d, new_max)
        return max_d

    return helper(1)
