def check_expression(expression):
    """
    Checks if all brackets in the expression are balanced.
    Supports: (), [], {} combinations.
    """
    stack = []

    for char in expression:
        if char == '(':
            stack.append(')')
        elif char == '[':
            stack.append(']')
        elif char == '{':
            stack.append('}')

        # If it's a closing bracket, try to pop the matching opener
        else:
            if not stack:
                return False  # Found closing bracket without opening one
            top = stack.pop()

            # Check if this closing bracket matches the most recent opening
            if char == ')' and top != '(':
                return False
            elif char == ']' and top != '[':
                return False
            elif char == '}' and top != '{':
                return False

    return len(stack) == 0  # All brackets must be matched
```

