def remove_nested(t):
    result = []
    for item in t:
        if not isinstance(item, tuple):
            result.append(item)
        else:
            continue
    return tuple(result)

assert remove_nested((1, 5, 7, (4, 6), 10)) == (1, 5, 7, 10)
